import{_ as t,o,c as s,a3 as a}from"./chunks/framework.CMZ50_DS.js";const p=JSON.parse('{"title":"The API says the words on request","description":"","frontmatter":{"status":"accepted","date":"2026-11-14T00:00:00.000Z"},"headers":[],"relativePath":"docs/adr/0027-the-api-says-the-words-on-request.md","filePath":"docs/adr/0027-the-api-says-the-words-on-request.md"}'),n={name:"docs/adr/0027-the-api-says-the-words-on-request.md"};function r(d,e,i,h,c,l){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="the-api-says-the-words-on-request" tabindex="-1">The API says the words on request <a class="header-anchor" href="#the-api-says-the-words-on-request" aria-label="Permalink to &quot;The API says the words on request&quot;">​</a></h1><p>Builds on <a href="./0020-every-credential-resolves-to-one-caller">ADR 0020</a> and <a href="./0021-the-landing-site-the-app-and-the-api-have-their-own-hostname">ADR 0021</a>.</p><p>The signed-in website shows the account&#39;s workouts the way the phone does: &quot;Sets · 5 exercises · about 40 min&quot;, the muscles worked, the prescription of each step. That wording (and the muscle heat behind the body map) is decided once, in the shared Kotlin core, in English and French. The website must not grow a second copy of it in TypeScript.</p><ul><li><strong>The server builds the words.</strong> <code>GET /api/v1/workouts</code> and <code>GET /api/v1/workouts/{id}</code> read the latest version of each workout and the sessions done, and build the list and the page with the shared <code>WorkoutViews</code>, the same code the phone&#39;s library and workout page use.</li><li><strong>Words come on request, not by default.</strong> Every answer carries structured values only. A route that can say more takes <code>include</code>, with one or several values, comma separated or repeated (<code>include=text</code>), like GitLab&#39;s API. A plain API call (a script, a future client) is not padded with text, and later routes can add other extras. An unknown value is 400 <code>bad-query</code>. We chose this over a separate endpoint for the wording (two calls to join, and a list would need one per row) and over always sending text (it pollutes pure calls and fixes one language in the payload).</li><li><strong>The language</strong> is the first of <code>Accept-Language</code> the app has words for, otherwise the account&#39;s language. The answer says <code>Content-Language</code> and <code>Vary: Accept-Language</code>.</li><li><strong>Read-only.</strong> The website holds the <code>workouts:read</code> scope like every first-party client and never writes: the phone is the source of truth (<a href="./../accounts#sync">Accounts, Sync</a>).</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The server depends on the <code>shared</code> module for this one class and the wording behind it, which brings the phone&#39;s database and Bluetooth code onto its classpath. A <code>// CLEANUP:</code> in <code>WorkoutViews</code> marks it: move the wording into its own module the phone and the server both depend on.</li><li>Each new website page that shows computed words adds an <code>include=text</code> view next to its route, tested at the HTTP seam.</li></ul>',6)])])}const w=t(n,[["render",r]]);export{p as __pageData,w as default};
